1	//! A checker type reduced to the existing [`PropType`], where that is lossless; otherwise the checker's own text as a
2	//! `Named` type. The output schema is unchanged: nothing here adds a variant.
3	
4	use std::future::Future;
5	use std::pin::Pin;
6	use std::sync::{Arc, Mutex};
7	
8	use caliper_docgen_core::types::{FunctionParam, ObjectField, PropType};
9	use rustc_hash::FxHashMap;
10	
11	use crate::rpc::{CallError, Rpc, SymbolInfo, TypeInfo, flag};
12	
13	/// Nesting past which a type is written as the checker prints it.
14	const MAX_DEPTH: u8 = 4;
15	/// An inline object type with more fields than this is written as the checker prints it.
16	const MAX_INLINE_FIELDS: usize = 16;
17	
18	type Cache = Mutex<FxHashMap<(u64, u8), PropType>>;
19	type Converted<'a> = Pin<Box<dyn Future<Output = Result<PropType, CallError>> + Send + 'a>>;
20	
21	#[derive(Clone)]
22	pub(crate) struct Converter {
23	    rpc: Arc<Rpc>,
24	    cache: Arc<Cache>,
25	}
26	
27	impl Converter {
28	    pub(crate) fn new(rpc: Arc<Rpc>) -> Self {
29	        Self { rpc, cache: Arc::new(Mutex::new(FxHashMap::default())) }
30	    }
31	
32	    pub(crate) fn convert<'a>(&'a self, info: &'a TypeInfo, depth: u8) -> Converted<'a> {
33	        Box::pin(async move {
34	            let key = (info.id, depth);
35	            if let Some(hit) = self.cache.lock().ok().and_then(|cache| cache.get(&key).cloned()) {
36	                return Ok(hit);
37	            }
38	            let converted = self.uncached(info, depth).await?;
39	            if let Ok(mut cache) = self.cache.lock() {
40	                cache.insert(key, converted.clone());
41	            }
42	            Ok(converted)
43	        })
44	    }
45	
46	    async fn uncached(&self, info: &TypeInfo, depth: u8) -> Result<PropType, CallError> {
47	        let flags = info.flags;
48	        let simple = [
49	            (flag::ANY, PropType::Any),
50	            (flag::UNKNOWN, PropType::Unknown),
51	            (flag::UNDEFINED, PropType::Undefined),
52	            (flag::NULL, PropType::Null),
53	            (flag::VOID, PropType::Void),
54	            (flag::NEVER, PropType::Never),
55	            (flag::STRING, PropType::String),
56	            (flag::NUMBER, PropType::Number),
57	            (flag::BOOLEAN, PropType::Boolean),
58	            // A pattern such as `var(--${string})` or `Uppercase<string>` stands for strings.
59	            (flag::TEMPLATE_LITERAL | flag::STRING_MAPPING, PropType::String),
60	        ];
61	        if let Some((_, known)) = simple.into_iter().find(|(bit, _)| flags & bit != 0) {
62	            return Ok(known);
63	        }
64	        if flags & (flag::ENUM_LITERAL | flag::ENUM | flag::TYPE_PARAMETER) != 0 {
65	            return self.named(info).await;
66	        }
67	        if flags & flag::STRING_LITERAL != 0 {
68	            return match info.value.as_ref().and_then(|value| value.as_str()) {
69	                Some(text) => Ok(PropType::StringLiteral(text.to_string())),
70	                None => self.named(info).await,
71	            };
72	        }
73	        if flags & flag::NUMBER_LITERAL != 0 {
74	            return match info.value.as_ref().and_then(|value| value.as_f64()) {
75	                Some(number) => Ok(PropType::NumberLiteral(number)),
76	                None => self.named(info).await,
77	            };
78	        }
79	        // The beta's responses carry neither `value` nor `intrinsicName` for `true` and `false`.
80	        if flags & flag::BOOLEAN_LITERAL != 0 {
81	            return Ok(PropType::BoolLiteral(self.rpc.type_to_string(info.id).await? == "true"));
82	        }
83	        if depth >= MAX_DEPTH {
84	            return self.named(info).await;
85	        }
86	        if flags & flag::UNION != 0 {
87	            return self.union(info, depth).await;
88	        }
89	        if flags & flag::INTERSECTION != 0 {
90	            return self.intersection(info, depth).await;
91	        }
92	        if flags & flag::OBJECT != 0 {
93	            return self.object(info, depth).await;
94	        }
95	        self.named(info).await
96	    }
97	
98	    async fn named(&self, info: &TypeInfo) -> Result<PropType, CallError> {
99	        Ok(PropType::Named { name: self.rpc.type_to_string(info.id).await?.into(), args: Vec::new() })
100	    }
101	
102	    /// `ReactNode` is a union alias of a dozen members; the alias is what the structural result reports too.
103	    async fn react_alias(&self, info: &TypeInfo) -> Result<Option<PropType>, CallError> {
104	        let Some(SymbolInfo { name, .. }) = self.rpc.alias_symbol(info.id).await? else { return Ok(None) };
105	        Ok(match name.as_str() {
106	            "ReactNode" => Some(PropType::ReactNode),
107	            "ElementType" => Some(PropType::ElementType),
108	            _ => None,
109	        })
110	    }
111	
112	    async fn members(&self, info: &TypeInfo, depth: u8) -> Result<Vec<PropType>, CallError> {
113	        let mut converted = Vec::new();
114	        for member in self.rpc.members(info.id).await? {
115	            converted.push(self.convert(&member, depth + 1).await?);
116	        }
117	        Ok(converted)
118	    }
119	
120	    async fn union(&self, info: &TypeInfo, depth: u8) -> Result<PropType, CallError> {
121	        if let Some(known) = self.react_alias(info).await? {
122	            return Ok(known);
123	        }
124	        let mut flat = Vec::new();
125	        for member in self.members(info, depth).await? {
126	            match member {
127	                PropType::Union(inner) => flat.extend(inner),
128	                other => flat.push(other),
129	            }
130	        }
131	        // `boolean` is the union `false | true`.
132	        let has_both = flat.contains(&PropType::BoolLiteral(true)) && flat.contains(&PropType::BoolLiteral(false));
133	        let mut members: Vec<PropType> = Vec::new();
134	        for member in flat {
135	            let member = match member {
136	                PropType::BoolLiteral(_) if has_both => PropType::Boolean,
137	                other => other,
138	            };
139	            if !members.contains(&member) {
140	                members.push(member);
141	            }
142	        }
143	        Ok(if members.len() == 1 { members.swap_remove(0) } else { PropType::Union(members) })
144	    }
145	
146	    async fn intersection(&self, info: &TypeInfo, depth: u8) -> Result<PropType, CallError> {
147	        // `string & {}` (the keep-the-literals trick) is a string.
148	        let mut members: Vec<PropType> = self
149	            .members(info, depth)
150	            .await?
151	            .into_iter()
152	            .filter(|member| !matches!(member, PropType::Object(fields) if fields.is_empty()))
153	            .collect();
154	        Ok(if members.len() == 1 { members.swap_remove(0) } else { PropType::Intersection(members) })
155	    }
156	
157	    async fn object(&self, info: &TypeInfo, depth: u8) -> Result<PropType, CallError> {
158	        if info.is_tuple_type {
159	            let mut elements = Vec::new();
160	            for element in self.rpc.type_arguments(info.id).await? {
161	                elements.push(self.convert(&element, depth + 1).await?);
162	            }
163	            return Ok(PropType::Tuple(
164	                elements.into_iter().map(caliper_docgen_core::types::TupleElement::required).collect(),
165	            ));
166	        }
167	        if info.object_flags & flag::OBJECT_REFERENCE != 0 && self.rpc.is_array(info.id).await? {
168	            let arguments = self.rpc.type_arguments(info.id).await?;
169	            let Some(element) = arguments.first() else { return self.named(info).await };
170	            return Ok(PropType::Array(Box::new(self.convert(element, depth + 1).await?)));
171	        }
172	        let text = self.rpc.type_to_string(info.id).await?;
173	        match text.as_str() {
174	            "CSSProperties" | "React.CSSProperties" => return Ok(PropType::CssProperties),
175	            "JSX.Element" | "Element" => return Ok(PropType::ReactNode),
176	            _ if text.starts_with("ReactElement<") => return Ok(PropType::ReactNode),
177	            _ => {}
178	        }
179	        if text.starts_with('(') || text.starts_with('<') {
180	            return self.function(info, depth, text).await;
181	        }
182	        if text.starts_with('{') {
183	            return self.inline_object(info, depth, text).await;
184	        }
185	        Ok(PropType::Named { name: text.into(), args: Vec::new() })
186	    }
187	
188	    async fn function(&self, info: &TypeInfo, depth: u8, text: String) -> Result<PropType, CallError> {
189	        let signatures = self.rpc.signatures(info.id).await?;
190	        let [signature] = signatures.as_slice() else {
191	            return Ok(PropType::Named { name: text.into(), args: Vec::new() });
192	        };
193	        let parameters = self.rpc.parameters(signature.id).await?;
194	        let references: Vec<_> = parameters.iter().map(|parameter| &parameter.reference).collect();
195	        let types = if references.is_empty() { Vec::new() } else { self.rpc.types_of_symbols(&references).await? };
196	        // The checker's parameter symbols say neither which parameter is optional nor which is the rest parameter;
197	        // its printed signature does (`percent?: number`, `...rest: string[]`), and its signature flags say whether
198	        // the last parameter is a rest parameter. A printed signature that does not parse into one entry per
199	        // parameter (a long one is cut short) leaves the markers off, as before.
200	        let markers = parameter_markers(&text).filter(|markers| markers.len() == parameters.len());
201	        let has_rest = signature.flags & flag::SIGNATURE_HAS_REST_PARAMETER != 0;
202	        let mut params = Vec::new();
203	        for (index, (parameter, ty)) in parameters.iter().zip(&types).enumerate() {
204	            let marker = markers.as_ref().and_then(|markers| markers.get(index)).copied().unwrap_or_default();
205	            let rest = marker.rest || (has_rest && index + 1 == parameters.len());
206	            let optional = marker.optional && !rest;
207	            let param_type = without_undefined(self.convert(ty, depth + 1).await?, optional);
208	            params.push(FunctionParam { name: Some(parameter.name.clone()), param_type, optional, rest });
209	        }
210	        let return_type = self.rpc.return_type(signature.id).await?;
211	        Ok(PropType::Function {
212	            type_params: Vec::new(),
213	            params,
214	            return_type: Box::new(self.convert(&return_type, depth + 1).await?),
215	        })
216	    }
217	
218	    async fn inline_object(&self, info: &TypeInfo, depth: u8, text: String) -> Result<PropType, CallError> {
219	        let properties = self.rpc.properties(info.id).await?;
220	        if properties.is_empty() || properties.len() > MAX_INLINE_FIELDS {
221	            return Ok(PropType::Named { name: text.into(), args: Vec::new() });
222	        }
223	        let references: Vec<_> = properties.iter().map(|property| &property.reference).collect();
224	        let types = self.rpc.types_of_symbols(&references).await?;
225	        let mut fields = Vec::new();
226	        for (property, ty) in properties.iter().zip(&types) {
227	            let required = property.flags & flag::SYMBOL_OPTIONAL == 0;
228	            fields.push(ObjectField::new(
229	                property.name.clone(),
230	                without_undefined(self.convert(ty, depth + 1).await?, !required),
231	                required,
232	                String::new(),
233	            ));
234	        }
235	        Ok(PropType::Object(fields))
236	    }
237	}
