339	/// An optional prop's type includes `undefined`; react-docgen-typescript drops it, as does the structural result.
340	pub(crate) fn without_undefined(prop_type: PropType, optional: bool) -> PropType {
341	    match prop_type {
342	        PropType::Union(members) if optional => {
343	            let mut kept: Vec<PropType> = members.into_iter().filter(|m| *m != PropType::Undefined).collect();
344	            if kept.len() == 1 { kept.swap_remove(0) } else { PropType::Union(kept) }
345	        }
346	        other => other,
347	    }
348	}
