391	        assert_eq!(parameter_markers("<T>(value: T, key?: keyof T) => T"), Some(vec![REQUIRED, OPTIONAL]));
392	        assert_eq!(parameter_markers("<T extends { a?: 1 }, U = (x?: 1) => 2>(v: T) => U"), Some(vec![REQUIRED]));
393	        assert_eq!(parameter_markers("(__0: { a: string }, __1?: number) => void"), Some(vec![REQUIRED, OPTIONAL]));
