417	/// Why a call failed, split by whether the rest of the run can go on.
418	#[derive(Debug)]
419	pub(crate) enum CallError {
420	    /// The session is gone or stuck: every later call would fail the same way.
421	    Fatal(String),
422	    /// The checker rejected this one call; other components may still resolve.
423	    Rejected(String),
424	}
