async fn run(request: SemanticRequest) -> SemanticOutcome {
    if !request.targets.iter().any(|target| target.exported) {
        return group_by_file(&request).0;
    }
    let config = match supervisor_config(&request) {
        Ok(config) => config,
        Err(reason) => return SemanticOutcome::unavailable(reason),
    };
    let supervisor = match Supervisor::spawn(config).await {
        Ok(supervisor) => supervisor,
        Err(error) => return SemanticOutcome::unavailable(error.to_string()),
    };
    let outcome = answer_with(&supervisor, &request).await;
    supervisor.shutdown().await.ok();
    outcome
}

/// Answers the request's targets with a checker that is already running: one program rooted at their files.
async fn answer_with(supervisor: &Supervisor, request: &SemanticRequest) -> SemanticOutcome {
    let (mut outcome, by_file, order) = group_by_file(request);
    if order.is_empty() {
        return outcome;
    }
    let files: Vec<String> = order.iter().map(|file| file.to_string()).collect();
    match session(supervisor, request, &files, &by_file, &order).await {
        Ok(mut answered) => {
            outcome.components.append(&mut answered.components);
            outcome.fallbacks.append(&mut answered.fallbacks);
            outcome
        }
        Err(error) => SemanticOutcome::unavailable(format!("the checker stopped answering: {error}")),
    }
}

async fn session(
    supervisor: &Supervisor,
    request: &SemanticRequest,
    files: &[String],
    by_file: &FxHashMap<&Utf8Path, Vec<&Target>>,
    order: &[&Utf8Path],
) -> Result<SemanticOutcome, CallError> {
    let started = std::time::Instant::now();
    let opened = match &request.prepared_options {
        Some(options) => {
            Rpc::open_with(supervisor.client(), request.request_timeout, options, files, request.record_to.is_some())
                .await
        }
        None => {
            Rpc::open(
                supervisor.client(),
                request.request_timeout,
                request.tsconfig.as_ref().map(|path| path.as_str()),
                files,
                request.record_to.is_some(),
            )
            .await
        }
    };
    let rpc = Arc::new(opened?);
    let opened = started.elapsed();
    let converter = Converter::new(rpc.clone());
    let limit = Arc::new(Semaphore::new(FILES_IN_FLIGHT));
    let interner = Arc::new(PropInterner::default());

    let mut tasks = JoinSet::new();
    for file in order {
        let targets: Vec<Target> = by_file.get(file).into_iter().flatten().map(|target| (*target).clone()).collect();
        let (rpc, converter, limit, interner) = (rpc.clone(), converter.clone(), limit.clone(), interner.clone());
        tasks.spawn(async move {
            let _permit = limit.acquire().await;
            answer_file(&rpc, &converter, &interner, targets).await
        });
    }

    let mut outcome = SemanticOutcome::default();
    let mut failure = None;
    while let Some(joined) = tasks.join_next().await {
        match joined {
            Ok(Ok(mut answered)) => {
                outcome.components.append(&mut answered.components);
                outcome.fallbacks.append(&mut answered.fallbacks);
            }
            Ok(Err(error)) => {
                failure = Some(error);
                tasks.abort_all();
            }
            // A panic inside a worker must not silently leave its components structural.
            Err(joined) if joined.is_panic() => {
                failure = Some(CallError::Fatal("a worker panicked".to_string()));
                tasks.abort_all();
            }
            // A cancelled task is one this loop aborted after a failure.
            Err(_cancelled) => {}
        }
    }
    if let Some(error) = failure {
        return Err(error);
    }

    if let (Some(path), Some(recording)) = (&request.record_to, rpc.recording())
        && let Ok(json) = serde_json::to_string_pretty(&recording)
        && let Err(error) = std::fs::write(path, json)
    {
        tracing::warn!("could not write the recording to {path}: {error}");
    }
    tracing::debug!(
        requests = ?rpc.calls(),
        files = files.len(),
        program_ms = opened.as_millis() as u64,
        total_ms = started.elapsed().as_millis() as u64,
        "semantic backend finished"
    );
    rpc.release().await;
    outcome.components.sort_by(|a, b| (&a.file_path, &a.display_name).cmp(&(&b.file_path, &b.display_name)));
    outcome.fallbacks.sort_by(|a, b| (&a.file_path, &a.display_name).cmp(&(&b.file_path, &b.display_name)));
    Ok(outcome)
}

fn fallback_of(target: &Target, reason: &str) -> SemanticFallback {
    SemanticFallback {
        file_path: target.file_path.clone(),
        display_name: target.display_name.clone(),
        reason: reason.to_string(),
    }
}

/// A fatal error aborts the run; a call the checker rejected only sends that component to its structural result.
async fn answer_file(
    rpc: &Rpc,
    converter: &Converter,
    interner: &PropInterner,
    targets: Vec<Target>,
) -> Result<SemanticOutcome, CallError> {
    let mut outcome = SemanticOutcome::default();
    let Some(first) = targets.first() else { return Ok(outcome) };
    let exports = match module_exports(rpc, first.file_path.as_str()).await {
        Ok(Some(exports)) => exports,
        Ok(None) | Err(CallError::Rejected(_)) => {
            outcome
                .fallbacks
                .extend(targets.iter().map(|target| fallback_of(target, "not part of the checker's program")));
            return Ok(outcome);
        }
        Err(fatal) => return Err(fatal),
    };

    for target in &targets {
        match component::props_of(rpc, converter, interner, &exports, target).await {
            Ok(Answer::Props(props)) => outcome.components.push(SemanticComponent {
                file_path: target.file_path.clone(),
                display_name: target.display_name.clone(),
                props,
            }),
            Ok(Answer::Fallback(reason)) => outcome.fallbacks.push(fallback_of(target, &reason)),
            Err(CallError::Rejected(message)) => {
                outcome.fallbacks.push(fallback_of(target, &format!("the checker rejected a request: {message}")));
            }
            Err(fatal) => return Err(fatal),
        }
    }
    Ok(outcome)
}

async fn module_exports(rpc: &Rpc, file: &str) -> Result<Option<Vec<rpc::SymbolInfo>>, CallError> {
    let Some(module) = rpc.source_file_symbol(file).await? else { return Ok(None) };
    Ok(Some(rpc.exports_of_module(&module.reference).await?))
}
//! One component's props from the checker: the export's call signature, its first parameter's type, that type's
//! properties.

use std::sync::Arc;

use caliper_docgen_core::types::semantic::{PropInterner, SemanticProp};

use crate::Target;
use crate::convert::{Converter, without_undefined};
use crate::rpc::{CallError, Rpc, SymbolInfo, flag};

pub(crate) enum Answer {
    Props(Vec<Arc<SemanticProp>>),
    /// The component keeps its structural result, for this reason.
    Fallback(String),
}

/// `declarations` entries read `"<nodeId>.<pos>.<path>"`.
fn declared_in(declaration: &str) -> &str {
    declaration.splitn(3, '.').nth(2).unwrap_or("")
}

/// What `@types/react` declares (`key`, `ref`, `children` on `PropsWithChildren`, HTML attributes). Reported with the
/// flag set when the request asks for the name; what to do with them is the session's policy, not ours.
fn is_react_declared(property: &SymbolInfo) -> bool {
    property.declarations.iter().any(|declaration| declared_in(declaration).contains("/@types/react/"))
}

/// The export names a component may have. A display name is not always the export: Mantine sets
/// `displayName = "@mantine/core/Accordion"` on the export `Accordion`, and a static one reads `Menu.Item`.
fn candidate_names(display_name: &str) -> Vec<&str> {
    let mut names = vec![display_name];
    for separator in ['/', '.'] {
        if let Some((_, last)) = display_name.rsplit_once(separator)
            && !last.is_empty()
            && !names.contains(&last)
        {
            names.push(last);
        }
    }
    names
}

fn fallback(reason: &str) -> Result<Answer, CallError> {
    Ok(Answer::Fallback(reason.to_string()))
}

pub(crate) async fn props_of(
    rpc: &Rpc,
    converter: &Converter,
    interner: &PropInterner,
    exports: &[SymbolInfo],
    target: &Target,
) -> Result<Answer, CallError> {
    let display_name = target.display_name.as_str();
    let export = candidate_names(display_name)
        .into_iter()
        .find_map(|name| exports.iter().find(|symbol| symbol.name == name))
        .or_else(|| exports.iter().find(|symbol| symbol.name == "default"));
    let Some(export) = export else { return fallback("not found among the module's exports") };

    let mut reference = export.reference.clone();
    if export.flags & flag::SYMBOL_ALIAS != 0 {
        reference = rpc.aliased_symbol(&reference).await?.reference;
    }

    let component = rpc.type_of_symbol(&reference).await?;
    let signatures = rpc.signatures(component.id).await?;
    let [signature] = signatures.as_slice() else {
        return fallback(if signatures.is_empty() {
            "no call signature (class or non-function component)"
        } else {
            "overloaded call signatures"
        });
    };
    let parameters = rpc.parameters(signature.id).await?;
    let Some(first) = parameters.first() else { return fallback("takes no props parameter") };

    let props_type = rpc.type_of_symbol(&first.reference).await?;
    if props_type.flags & (flag::ANY | flag::UNKNOWN | flag::UNION | flag::TYPE_PARAMETER) != 0 {
        return fallback("props type is any, unknown, generic or a union");
    }

    let own: Vec<SymbolInfo> = rpc
        .properties(props_type.id)
        .await?
        .into_iter()
        .filter(|property| {
            !is_react_declared(property)
                || target.react_wanted.as_ref().is_none_or(|wanted| wanted.contains(&property.name))
        })
        .collect();
    let references: Vec<_> = own.iter().map(|property| &property.reference).collect();
    let types = if references.is_empty() { Vec::new() } else { rpc.types_of_symbols(&references).await? };

    let mut props = Vec::with_capacity(own.len());
    for (property, ty) in own.iter().zip(&types) {
        let required = property.flags & flag::SYMBOL_OPTIONAL == 0;
        let react_declared = is_react_declared(property);
        props.push(interner.share(SemanticProp {
            name: property.name.clone(),
            prop_type: without_undefined(converter.convert(ty, 0).await?, !required),
            required,
            react_declared,
            // React's own descriptions are the structural pass's to give, and fetching one per attribute is a call each.
            description: if react_declared || target.described.contains(&property.name) {
                String::new()
            } else {
                rpc.documentation(&property.reference).await?
            },
        }));
    }
    Ok(Answer::Props(props))
}

#[cfg(test)]
mod tests {
    use super::*;

    fn property(declaration: &str) -> SymbolInfo {
        SymbolInfo {
            reference: serde_json::Value::Null,
            name: "x".to_string(),
            flags: 4,
            declarations: vec![declaration.to_string()],
        }
    }

    #[test]
    fn the_declaring_path_is_what_follows_the_node_id_and_position() {
        assert_eq!(
            declared_in("48.264./proj/node_modules/@types/react/index.d.ts"),
            "/proj/node_modules/@types/react/index.d.ts"
        );
        assert_eq!(declared_in("garbage"), "");
    }

    #[test]
    fn a_display_name_with_a_package_or_namespace_prefix_also_tries_its_last_segment() {
        assert_eq!(candidate_names("Button"), ["Button"]);
        assert_eq!(candidate_names("@mantine/core/Accordion"), ["@mantine/core/Accordion", "Accordion"]);
        assert_eq!(candidate_names("Menu.Item"), ["Menu.Item", "Item"]);
    }

    #[test]
    fn only_properties_declared_in_types_react_are_excluded() {
        assert!(is_react_declared(&property("1.2./p/node_modules/@types/react/index.d.ts")));
        assert!(!is_react_declared(&property("1.2./p/src/button.tsx")));
        assert!(!is_react_declared(&property("1.2./p/node_modules/@chakra-ui/react/dist/index.d.ts")));
    }
}

