import { API } from 'tsrs/sync';
import { dump } from './hist.mjs';
import fs from 'node:fs';
import { makeConverter, SF, TF } from './convert.mjs';

const CWD = process.env.PROJ ?? '/tmp/claude-501/deepdive/proj';
const FILES = (process.env.FILES ?? 'src/Cases.tsx,src/rdt_types.tsx,src/rdt_memo.tsx').split(',').map((f) => `${CWD}/${f}`);
const ONLY_ROOTS = process.env.ROOTS !== 'all';
const out = process.env.OUT ?? '/tmp/claude-501/deepdive/proto_out.json';

const api = new API({ cwd: CWD, collectTiming: true });
const reqs = () => api.getTimingInfo().totals; // note: the call itself adds one request
const t0 = performance.now();
const snap = api.createSnapshot({ openProjects: [`${CWD}/${process.env.TSCONFIG ?? "tsconfig.json"}`] });
const proj = snap.getConfiguredProject(`${CWD}/${process.env.TSCONFIG ?? "tsconfig.json"}`);
const tSnap = performance.now() - t0;
const checker = proj.checker;
const stats = {};
const { conv } = makeConverter(checker, stats);

function discover(file) {
  const sf = proj.program.getSourceFile(file);
  const mod = checker.getSymbolOfSourceFile(sf.fileName);
  const found = [];
  for (const ex of checker.getExportsOfModule(mod)) {
    let s = ex;
    if (s.flags & SF.Alias) s = checker.getAliasedSymbol(s);
    if (!(s.flags & (SF.Function | SF.Class | 111551 & ~0 /*value*/))) continue;
    if (s.flags & (SF.Interface | SF.TypeAlias) && !(s.flags & 111551)) continue;
    const ty = checker.getTypeOfSymbol(s);
    const sigs = [...ty.getCallSignatures(), ...ty.getConstructSignatures()];
    if (!sigs.length) continue;
    found.push({ export: ex.name, symbol: s, type: ty, sigs });
  }
  return found;
}

function propsOf(c) {
  const sig = c.sigs[0];
  const isCtor = sig.isConstruct;
  let propsType;
  if (isCtor) {
    // class: props = first type argument of the base React.Component<P>, via the instance type's `props` property
    const inst = sig.getReturnType();
    const p = inst.getProperty('props');
    propsType = p ? checker.getTypeOfSymbol(p) : null;
  } else {
    const ps = sig.getParameters();
    if (!ps.length) return null;
    propsType = checker.getTypeOfSymbol(ps[0]);
  }
  if (!propsType) return null;
  let t = propsType;
  const generic = !!(t.flags & (TF.TypeParameter | TF.Conditional | TF.IndexedAccess));
  // apparent properties resolve a generic props type through its base constraint, like RDT does
  const base = checker.getBaseConstraintOfType(t);
  if (base) t = base;
  const members = t.flags & TF.Union ? t.getTypes() : [t];
  const props = new Map();
  for (const m of members) for (const p of checker.getPropertiesOfType(m)) if (!props.has(p.name)) props.set(p.name, p);
{
  "name": "proto",
  "version": "1.0.0",
  "description": "",
  "main": "index.js",
  "scripts": {
    "test": "echo \"Error: no test specified\" && exit 1"
  },
  "keywords": [],
  "author": "",
  "license": "ISC",
  "type": "module",
  "dependencies": {
    "@types/node": "^26.6.6",
    "@types/react": "^18.3.31",
    "tsrs": "^0.23.0-ts7.1.0-beta"
  }
}
