const CWD = '/tmp/claude-501/deepdive/proj';
const api = new API({ cwd: CWD });
const tsconfig = `${CWD}/tsconfig.json`;
const snap = api.createSnapshot({ openProjects: [tsconfig] });
const proj = snap.getConfiguredProject(tsconfig);
const c = api.client;
const raw = (m, p) => c.apiRequest(m, { snapshot: snap.id, project: proj.id, ...p });
const show = (label, v) => console.log(label, JSON.stringify(v));
const file = `${CWD}/src/Cases.tsx`;
const mod = raw('getSymbolOfSourceFile', { file });
const exports = raw('getExportsOfModule', { symbol: mod.reference });
const e = exports.find((x) => x.name === process.argv[2]);
const t = raw('getTypeOfSymbol', { symbol: e.reference });
const sigs = raw('getSignaturesOfType', { type: t.id, kind: 0 });
const ps = raw('getParametersOfSignature', { objectId: sigs[0].id });
const pt = raw('getTypeOfSymbol', { symbol: ps[0].reference });
const properties = raw('getPropertiesOfType', { type: pt.id });
const types = raw('getTypesOfSymbols', { symbols: properties.map((p) => p.reference) });
const i = properties.findIndex((p) => p.name === process.argv[3]);
let ty = types[i];
show('prop type', ty);
if (ty.flags & 134217728) { const ms = raw('getTypesOfType', { objectId: ty.id }); show('members', ms); ty = ms.find((m) => m.flags & 1048576) ?? ty; }
const fsigs = raw('getSignaturesOfType', { type: ty.id, kind: 0 });
show('fsigs', fsigs);
const fps = raw('getParametersOfSignature', { objectId: fsigs[0].id });
for (const p of fps) show('param', { ...p, reference: undefined });
show('ts', raw('typeToString', { type: ty.id }));
show('ro', raw('isReadonlySymbol', { symbol: properties[i].reference }));

