import json, re, statistics, subprocess, sys

TSRS = '/tmp/claude-501/slice2/node_modules/@tsrs/darwin-arm64/tsrs'
BINS = {
    'main': '/tmp/claude-501/slice2/target-main/release/examples/ondemand_bench',
    'branch': '/Users/gabe/Projects/caliper/.claude/worktrees/agent-a594661a90cce2eff/target/release/examples/ondemand_bench',
}
PROJECTS = {
    'chakra': ('/tmp/claude-501/spike/proj/chakra', 8),
    'big': ('/tmp/claude-501/spike/proj/big', 1),
}
RUNS = int(sys.argv[1]) if len(sys.argv) > 1 else 9
only = sys.argv[2:] or list(PROJECTS)

results = {}
for project in only:
    path, count = PROJECTS[project]
    for run in range(1, RUNS + 1):
        for variant, binary in BINS.items():
            out = subprocess.run(
                ['/usr/bin/time', '-l', binary, '--src', path + '/src', '--tsc', TSRS, '--tsconfig', path + '/tsconfig.json', '--count', str(count), '--seed', str(run)],
                capture_output=True, text=True)
            line = [l for l in out.stdout.splitlines() if l.startswith('{')][-1]
            data = json.loads(line)
            rss = int(re.search(r'(\d+)\s+maximum resident set size', out.stderr).group(1)) / 1e6
            results.setdefault((project, variant), []).append((data, rss))

for (project, variant), runs in results.items():
    def med(f):
        return statistics.median(f(d, r) for d, r in runs)
    each = lambda d, r: sum(d.get('eachMs', [])) if d.get('eachMs') else 0
    print(project, variant,
          'first', round(med(lambda d, r: d['firstMs']), 1),
          'each-sum', round(med(each), 1),
          'total-after-start', round(med(lambda d, r: d['firstMs'] + each(d, r)), 1),
          'rss-MB', round(med(lambda d, r: r), 1),
          'props', runs[0][0].get('props'), 'answered', runs[0][0].get('answered'))
    print('   keys', sorted(runs[0][0].keys()))

