          'total-after-start', round(med(lambda d, r: d['firstMs'] + each(d, r)), 1),
          'rss-MB', round(med(lambda d, r: r), 1),
          'props', runs[0][0].get('props'), 'answered', runs[0][0].get('answered'))
    print('   keys', sorted(runs[0][0].keys()))

